<script lang="ts">
 import {page} from '$app/state';import {instalacao,dispensarInstalacao} from '#lib/pwa.svelte';import Icone from './Icone.svelte';
 let dialogo=$state<HTMLDialogElement>(null!);
 async function instalar(){if(instalacao.ios||!instalacao.convite){dialogo.showModal();return;}const e=instalacao.convite;instalacao.convite=null;try{await e.prompt();const escolha=await e.userChoice;if(escolha.outcome==='accepted'){instalacao.instalado=true;dispensarInstalacao();}}catch{dialogo.showModal();}}
</script>
{#if page.url.pathname==='/'&&instalacao.pronto&&instalacao.mobile&&!instalacao.instalado&&!instalacao.oculto}<section class="install-card mt-5" aria-label="Instalar Escala Local"><span class="install-icon"><Icone nome="baixar" tamanho={25}/></span><div><strong>Adicionar à Tela de Início</strong><p>Acesse pelo ícone no seu celular.</p></div><button class="btn btn-primario" type="button" onclick={instalar}>Adicionar à tela inicial</button><button class="btn btn-link" type="button" onclick={dispensarInstalacao}>Agora não</button></section>{/if}
<dialog bind:this={dialogo} class="install-dialog" aria-labelledby="instalar-titulo"><h2 id="instalar-titulo" class="titulo">Adicionar à Tela de Início</h2>{#if instalacao.ios}<p class="mt-3 text-sm">No iPhone ou iPad, abra no Safari e siga:</p><ol class="install-steps"><li>Toque em <strong>Compartilhar</strong>.</li><li>Escolha <strong>Adicionar à Tela de Início</strong>.</li><li>Confirme em <strong>Adicionar</strong>.</li></ol>{:else}<ol class="install-steps"><li>Abra o menu do Chrome ou Edge.</li><li>Escolha <strong>Adicionar à tela inicial</strong> ou <strong>Instalar aplicativo</strong>.</li><li>Confirme a instalação.</li></ol>{/if}<button class="btn btn-primario w-full mt-4" type="button" onclick={()=>dialogo.close()}>Entendi</button></dialog>
